// Play A play: one showing of a creative, formed from the evidence events that matched
// it. The trust score breakdown is internal and never exposed.
type Play struct {
	// LastResponse holds the HTTP details of the response behind this result.
	LastResponse *ResponseInfo `json:"-"`

	// Livemode False for an object in an integrator sandbox (test key), true otherwise.
	// Always set on each object directly under `data`; absent on the same kind of object
	// nested inside another.
	Livemode *bool  `json:"livemode"`
	ID       string `json:"id"`
	// ScreenID Null when the play happened on a screen not registered in Vojo (e.g. an
	// exchange's own screen).
	ScreenID *string `json:"screen_id"`
	// Screen The play's screen with its name, so lists render without a lookup per row;
	// null when `screen_id` is null.
	Screen          *NamedRef `json:"screen"`
	AdvertisementID *string   `json:"advertisement_id"`
	// Advertisement The play's advertisement (creative) with its name; null when
	// `advertisement_id` is null.
	Advertisement *NamedRef `json:"advertisement"`
	// ExternalPlayID The partner's per-play correlation id, echoed verbatim; never
	// verified.
	ExternalPlayID *string `json:"external_play_id"`
	Channel        *string `json:"channel"`
	// StartedAt Time of the earliest evidence event in the play.
	StartedAt string `json:"started_at"`
	// Tracks Vojo's two independent evidence sources for this play: `passport` (the
	// in-creative fingerprint) and `harvester` (the sensor on the glass). Raw per-track
	// status; never collapsed into a single verified flag.
	Tracks PlayTracks `json:"tracks"`
	// Verification Same score, band and phase the `verification.score.preliminary` /
	// `verification.score.final` webhooks send.
	Verification PlayVerification `json:"verification"`
	CreatedAt    string           `json:"created_at"`
	UpdatedAt    *string          `json:"updated_at"`
}

