type PlayPhase string

const (
	PlayPhasePreliminary PlayPhase = "preliminary"
	PlayPhaseFinal       PlayPhase = "final"
)

// PlayTrackStatus `absent`: no evidence from this source. `matched`: evidence that
// counted towards the score. `present`: a Harvester reading that arrived after the
// score became final, so it's recorded on the play but isn't in the score.
type PlayTrackStatus string

const (
	PlayTrackStatusAbsent  PlayTrackStatus = "absent"
	PlayTrackStatusPresent PlayTrackStatus = "present"
	PlayTrackStatusMatched PlayTrackStatus = "matched"
)

