// Wrapper A proof-of-display wrapper. Wrapping can finish inside the create request
// (`status: ready`) or continue in the background (`status: processing`); integrators
// must handle both.
type Wrapper struct {
	// LastResponse holds the HTTP details of the response behind this result.
	LastResponse *ResponseInfo `json:"-"`

	// Livemode False for an object in an integrator sandbox (test key), true otherwise.
	// Always set on each object directly under `data`; absent on the same kind of object
	// nested inside another.
	Livemode *bool `json:"livemode"`
	// ID Wrapper id. Opaque string — treat as an identifier, never parse it.
	ID string `json:"id"`
	// Status `processing`: the wrap is still being built — `url`, `html` and the
	// fingerprint fields are null until it is `ready`. Poll `GET
	// /v1/wrappers/{wrapper_id}` or subscribe to the `wrapper.ready` / `wrapper.failed`
	// webhooks. Clients must tolerate new values. One of: processing, ready, failed. New
	// values may appear.
	Status string `json:"status"`
	// Failure Why the wrap failed; null unless `status` is `failed`.
	Failure      *WrapperFailure     `json:"failure"`
	DeliveryMode WrapperDeliveryMode `json:"delivery_mode"`
	// URL Archived wrapper URL (`archive` mode); null for `inline`.
	URL *string `json:"url"`
	// HTML Wrapper HTML (`inline` mode); null for `archive`.
	HTML          *string `json:"html"`
	FingerprintID *string `json:"fingerprint_id"`
	// Fingerprint Fingerprint code burned into the wrapper, when requested.
	Fingerprint *string        `json:"fingerprint"`
	Metadata    map[string]any `json:"metadata"`
	// CreatedAt RFC 3339 / ISO-8601 UTC timestamp.
	CreatedAt string `json:"created_at"`
}

// WrapperDeliveryMode `inline` returns the wrapper HTML in the response; `archive`
